"""Construct traceable small cases from downloaded sources; no expected exports generated by EcoData."""
from pathlib import Path
import sys,shutil,json,hashlib,io
from datetime import timezone,timedelta
import numpy as np
import pandas as pd
import xarray as xr
src=Path(__file__).resolve().parents[2]
case=Path(__file__).resolve().parent
sys.path.insert(0,str(case))
from independent import surf,photolysis

def dump(path,obj):
    path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,ensure_ascii=False,indent=2,default=str),encoding='utf-8')
def copy(source,target):
    target.parent.mkdir(parents=True,exist_ok=True)
    if source.resolve()!=target.resolve():shutil.copy2(source,target)
fields=['wind_speed','wind_direction','ceiling','opaque_cover','temperature','relative_humidity','station_pressure','precip_code']
calcfg={'version':'CALMET-5.8.5-SURF-2.0','station_ids':[14732],'timezone_west_hours':5,'time_label':'hour_end','missing_policy':'preserve',
 'columns':{n:n for n in fields},'units':dict(zip(fields,['m/s','degree','hundred_ft','tenths','degC','%','hPa','code']))}
cal=case/'calpuff'
raw=cal/'raw/noaa_isd_2020.csv';copy(raw,cal/'raw/noaa_isd_2020.csv')
full=pd.read_csv(raw,dtype=str,keep_default_na=False)
df=full.loc[full.DATE.str.startswith('2020-01-01') & full.REPORT_TYPE.eq('FM-15')].copy()
# Official SMERGE5.57 READISH convention: reports (HH-1):01..HH:00
# belong to hour-ending HH. Select last FM-15 report per interval explicitly.
df['hour_end']=pd.to_datetime(df.DATE).dt.ceil('h')
df=df.sort_values('DATE').groupby('hour_end',sort=True).tail(1).sort_values('hour_end')
def part(raw,i,missing,scale=1,quality=None):
    parts=str(raw).split(',')
    if len(parts)<=i or parts[i] in {'',missing}:return np.nan
    if quality is not None and (len(parts)<=quality or parts[quality] not in {'1','5'}):return np.nan
    try:return float(parts[i])/scale
    except ValueError:return np.nan
rows=[]
for _,r in df.iterrows():
    opaque=str(r.get('GF1','')).split(',')
    # Only unambiguous none/full opaque codes. Okta ranges are not falsely treated as exact tenths.
    cover={'00':0,'08':10}.get(opaque[1] if len(opaque)>1 else '',np.nan)
    rows.append({'time':r.hour_end.isoformat()+'+00:00','observation_time':r.DATE+'+00:00','station_id':14732,
      'wind_speed':part(r.WND,3,'9999',10,4),'wind_direction':part(r.WND,0,'999',1,1),
      'temperature':part(r.TMP,0,'+9999',10,1),
      'ceiling':np.nan,'opaque_cover':cover,'relative_humidity':np.nan,
      'station_pressure':part(r.get('MA1',''),2,'99999',10,3),'precip_code':np.nan})
cal.mkdir(parents=True,exist_ok=True);pd.DataFrame(rows).to_csv(cal/'A_noaa_surface.csv',index=False)
dump(cal/'config_noaa.json',calcfg)
dump(cal/'normalization.json',{'raw_rows_selected':len(df),'selection':'2020-01-01 FM-15 reports; latest report in each (hour-1,hour] interval, official SMERGE5.57 READISH hour-end convention; actual observation_time retained',
 'quality':'Only NOAA QC 1/5 accepted; other flags become explicitly missing','variables_not_inferred':['relative humidity','ceiling unlimited flag','precipitation code'],
 'opaque_cover':'GF1 opaque coverage 00->0,08->10 only; intermediate okta ranges preserved as missing',
 'source_location':{'station':'72503014732','latitude':40.77944,'longitude':-73.88035,'elevation_m':3.4},
 'limitations':'Partial NOAA fields; missing values remain 9999 in B, this cannot prove a runnable meteorological simulation.'})
# Independent official B2 serialization case with unit changes in A; not upstream raw-data reconstruction.
b2=cal/'B2_official_smerge_SURF.DAT';copy(b2,cal/'B2_official_smerge_SURF.DAT')
ref=surf(b2);rows=[]
for i,t in enumerate(ref['times']):
    for j,station in enumerate(ref['stations']):
        v=ref['values'][i,j].copy();v[v==9999]=np.nan
        v[0]*=3.6;v[4]-=273.15;v[6]*=100
        row=dict(zip(fields,v));row.update(station_id=station,time=t.replace(tzinfo=timezone(timedelta(hours=-5))).isoformat());rows.append(row)
pd.DataFrame(rows).to_csv(cal/'A_reference_decoded.csv',index=False)
cfg=json.loads(json.dumps(calcfg));cfg.update(station_ids=ref['stations']);cfg['units'].update(wind_speed='km/h',station_pressure='Pa')
dump(cal/'config_reference.json',cfg)
# Complete synthetic surface example including leap day and year rollover with fixed LST.
cfg=json.loads(json.dumps(calcfg));cfg.update(station_ids=[12345],missing_policy='reject')
synth=pd.DataFrame([dict(station_id=12345,time=t.isoformat(),wind_speed=3,wind_direction=270,ceiling=20,opaque_cover=5,temperature=20,relative_humidity=50,station_pressure=1010,precip_code=0) for t in pd.date_range('2020-02-29T04:00:00Z',periods=4,freq='h')])
synth.to_csv(cal/'A_synthetic_complete.csv',index=False);dump(cal/'config_synthetic.json',cfg)

sw=case/'swat';raw=sw/'raw/noaa_gsod_2020.csv';copy(raw,sw/'raw/noaa_gsod_2020.csv')
df=pd.read_csv(raw);a=pd.DataFrame({'date':df.DATE,'precipitation':df.PRCP.where(df.PRCP!=99.99),'tmax':df.MAX.where(df.MAX!=9999.9),'tmin':df.MIN.where(df.MIN!=9999.9)})
# GSOD accumulation flags A/B/C/E/H/I are not silently reinterpreted as complete daily totals.
incomplete=~df.PRCP_ATTRIBUTES.isin(['D','F','G']);a.loc[incomplete,'precipitation']=np.nan
a.to_csv(sw/'A_daily_weather.csv',index=False)
dump(sw/'config.json',{'version':'SWAT-2012-daily-single-gauge','date_column':'date','date_semantics':'reported_daily_date','missing_policy':'swat_generator',
 'columns':{n:n for n in ['precipitation','tmax','tmin']},'units':{'precipitation':'inch','tmax':'degF','tmin':'degF'},
 'station':{'id':'72405013743','latitude':float(df.LATITUDE.iloc[0]),'longitude':float(df.LONGITUDE.iloc[0]),'elevation_m':float(df.ELEVATION.iloc[0]),'crs':'EPSG:4326'}})
dump(sw/'normalization.json',{'incomplete_precipitation_flags_count':int(incomplete.sum()),'policy':'Only 24-hour coverage D/F/G accepted; other flags -> NaN, mapped explicitly to -99.0 generator by user config',
 'window_warning':'GSOD maximum/minimum and precipitation reporting windows can differ from midnight calendar day; no timezone shift is made. Project acceptance remains required.'})

wrf=case/'wrf';raw=wrf/'raw/oisst_20200101.nc';copy(raw,wrf/'raw/oisst_20200101.nc')
with xr.open_dataset(io.BytesIO(raw.read_bytes()),engine='h5netcdf') as ds:
    small=ds.sel(lat=slice(30,31),lon=slice(300,301)).load()
small.to_netcdf(wrf/'A_sst_subset.nc',engine='h5netcdf')
dump(wrf/'config.json',{'version':'WPS-4.6-intermediate-v5-SST','variable':'sst','latitude':'lat','longitude':'lon','time':'time','squeeze_dimensions':['zlev'],'crs':'EPSG:4326','time_basis':'UTC','map_source':'NOAA OISST v2.1'})
dump(wrf/'normalization.json',{'selection':'Latitude 30..31N, longitude 300..301E, ocean only','time':'NOAA analyzed daily SST at original NetCDF label, not synthesized hourly observations','raw_attributes':dict(small.attrs),'sst_attributes':dict(small.sst.attrs)})

camx=case/'camx';raw=camx/'raw/tuv.do_CB6r5.20160610';copy(raw,camx/'raw/tuv.do_CB6r5.20160610')
ref=photolysis(raw);rows=[]
for i,height in enumerate(ref['heights']):
    for j,reaction in enumerate(ref['reactions']):
        for k,value in enumerate(ref['values'][i,j]):rows.append({'block_id':i,'ozone_column_native':ref['conditions'][i][0],'albedo':ref['conditions'][i][1],'terrain_native':ref['conditions'][i][2],'height_km':height,'reaction':reaction,'zenith_index':k,'photolysis_native_value':value})
pd.DataFrame(rows).to_csv(camx/'A_photolysis_table.csv',index=False)
dump(camx/'normalization.json',{'input_type':'CAMx7.40 TUV photolysis native reference input','title':ref['title'],'conditions':ref['condition_line'],
 'shape':ref['values'].shape,'condition_count':len(set(map(tuple,ref['conditions']))),'unique_height_count':len(set(ref['heights'])),'height_block_count':len(ref['heights']),'scope':'Native input -> independently decoded table with all O3/albedo/terrain conditions -> EcoData standardized CF only; no upstream radiation model or native CAMx export',
 'units':'Retained native file numbers; no unverified s^-1/min^-1 conversion, zenith columns retain indices until official source verification',
 'reference_configuration':'Official June10-11 2016 CAMx7.40 test, CB6r5; values are same file, not observed atmospheric data'})
copy(camx/'raw/README_official.txt',camx/'raw/README_official.txt')
copy(camx/'raw/CAMx_official_job.txt',camx/'raw/CAMx_official_job.txt')

cm=case/'cmaq'
for p in (src/'examples/cmaq_case/input').iterdir():copy(p,cm/'A_existing_case'/p.name)
copy(cm/'reference_format_only/ic_profile_CB05_CMAQ5.0.2.dat',cm/'reference_format_only/ic_profile_CB05_CMAQ5.0.2.dat')
copy(src/'examples/cmaq_case/source_manifest.json',cm/'source_manifest_original.json')
dump(cm/'config.json',{'profile':'cmaq','version':'CMAQ5.5 auxiliary only','observation_temporal_semantics':'mean','spatial_method':'bilinear','residual_method':'nearest','negative_policy':'clip','reference_profile_version':'5.0.2 - FORMAT REFERENCE ONLY, not B2'})
print('Prepared offline cases from retained raw sources:',case)
